	.ascii	"   Accordion    "	; bank 1
	.ascii	"  Piano Styles  "	; bank 2
	.ascii	"Jazz&Rock Organ "	; bank 3
	.ascii	"Church & Theatre"	; bank 4
	.ascii	"Light Orchestra "	; bank 5
	.ascii	"  Split Sounds  "	; bank 6
	.ascii	"Layer Production"	; bank 7
	.ascii	" Special DSP FX "	; bank 8
	.ascii	"     World      "	; bank 9

